 selected=pd.read_csv(out/'selected_stars.csv');players=pd.read_csv(root/'2025-26/team_season_topics/player_games.csv',dtype={'GAME_ID':str});games=pd.read_csv(root/'2025-26/team_season_topics/team_games.csv',dtype={'GAME_ID':str});games['date']=pd.to_datetime(games.GAME_DATE);advanced=pd.read_csv(root/'star_dependency_study/game_cache/2025-26_team_advanced.csv.gz',dtype={'GAME_ID':str});games.GAME_ID=games.GAME_ID.str.zfill(10);players.GAME_ID=players.GAME_ID.str.zfill(10);advanced.GAME_ID=advanced.GAME_ID.str.zfill(10);games=games.merge(advanced[['TEAM_ID','GAME_ID','POSS']],on=['TEAM_ID','GAME_ID'],validate='one_to_one');rng=np.random.default_rng(20261117);rows=[];draws=[];game_rows=[];manifest=[]
