  delta=pair[1]-pair[0];draws.append(dict(team=z.team,delta=delta.tolist()));g=games[games.TEAM_ID.eq(z.team_id)&games.date.between(z.window_start,z.window_end)].copy();played=set(players[players.TEAM_ID.eq(z.team_id)&players.PLAYER_ID.eq(z.star_id)].GAME_ID);g['star_played']=g.GAME_ID.isin(played);g['selected_star_id']=z.star_id;g['selected_star_name']=z.star_name;assert g.star_played.sum()==z.present_games and (~g.star_played).sum()==z.absent_games
