   keep=np.arange(len(x))!=i;f=Fit(x[keep],y[keep]);loo.append(dict(measure=measure,outcome=outcome,removed_team=team,slope=f.params[1],hc3_p=f.pvalues[1],r_squared=f.rsquared))
