 with PdfPages(out/'volume_player_dependency_summary.pdf') as pdf:
  fig,ax=plt.subplots(figsize=(15,7));x=np.arange(len(d));ax.bar(x-.2,d.prior_on_off_gap,.4,label='2024–25 selection-season on/off gap');ax.bar(x+.2,d.current_on_off_gap,.4,label='2025–26 on/off gap (descriptive)');ax.set_xticks(x,d.team,rotation=45);ax.axhline(0,color='grey',lw=.7);ax.set_ylabel('On-court minus off-court team ORtg (points/100 possessions)');ax.set_title('Observed on/off dependency | prior-season-selected players');ax.legend();fig.text(.5,.02,'Selection: Highest passes sent + received player in 2024–25; retained in first 10 games of 2025–26.\nThese are raw associations, not causal player effects. Current on/off covers the team’s full season, including later games after trades.',ha='center',fontsize=10);fig.tight_layout(rect=[0,.1,1,.96]);fig.savefig(out/'onoff_gaps.png',dpi=160);pdf.savefig(fig);plt.close(fig)
  for measure in ['equal_total','raw']:
   fig,axes=plt.subplots(1,2,figsize=(15,7))
   for ax,outcome in zip(axes,['signed','absolute']):
    x,y,fit=models[(measure,outcome)];z=s[(s.measure==measure)&(s.outcome==outcome)].iloc[0];ax.scatter(x,y,s=45,c='#287b9b')
    ax.set_xlim(x.min()-.5,x.max()+1.2);pad=max(np.ptp(y)*.12,.008);ax.set_ylim(min(0,y.min())-pad,y.max()+pad);occupied=[]
    for team,xx,yy in zip(sample.team,x,y):
     px,py=ax.transData.transform((xx,yy));best=(4,4)
